-- Conteúdo em inglês (o espanhol usa o mesmo): nome de personagens e trajes, rótulo das equipes
-- Meta, título e descrição das rotações e nome dos chefes da BAI.
-- Vazio = o site mostra o texto em português.
ALTER TABLE "Agent" ADD COLUMN "nameEn" TEXT;
ALTER TABLE "Uniform" ADD COLUMN "nameEn" TEXT;
ALTER TABLE "MetaTeam" ADD COLUMN "labelEn" TEXT;
ALTER TABLE "Rotation" ADD COLUMN "titleEn" TEXT, ADD COLUMN "descriptionEn" TEXT;
ALTER TABLE "BaiBoss" ADD COLUMN "nameEn" TEXT;

